// Morgen-Briefing und System-Mails (ALLY 33, BA5, Stefan 20.10.2026): zwei Seiten aus dem Register (morgen-briefing, system-mails).
// Daten wie ALLY 8: ally_web_arbeit (Briefing), arbeit_web_seite 'systemmails'. Aktionen mit den Namen und Feldern von ALLY 8:
// start (was=briefing, "Jetzt schicken"), systemmails (tage, Zusammenfassung). Liefert nur die Seitenbeschreibung (JSON).
// Karten Offen/Meldungen: Nebentext in den Text (schmale Karten neben dem Seitenfenster, sonst bricht der Text zeichenweise um)
// BA10 (Migration 69): Morgen-Briefing – Abschnitt „Letzte Briefings“ (ally_ergebnisse_ui, nur eigene), Lesen im Seitenfenster (er=<id>).
const knapp = u => { if (u && Array.isArray(u.karten)) for (const k of u.karten) for (const e of k.eintraege || []) if (e.neben) { e.text = String(e.text || '') + ' · ' + String(e.neben); delete e.neben; } return u; };
const E = $('Start').first().json;
const D = $input.first().json || {};
const F = E.funktion || {};
const P = E.parameter || {};
const seite = ['morgen-briefing', 'system-mails'].includes(String(E.seite || '')) ? String(E.seite) : 'morgen-briefing';
const titel = String(F.name || (seite === 'system-mails' ? 'System-Mails' : 'Morgen-Briefing'));
const kopf = { schluessel: seite, art: 'funktion', titel, beschreibung: String(F.beschreibung || ''), krumen: [{ text: 'Startseite', ziel: { seite: 'start' } }, { text: titel }] };
const zahnrad = /^[a-z0-9-]{1,40}$/.test(String(F.einstellungen_ziel || '')) ? { seite: 'einstellungen', parameter: { bereich: String(F.einstellungen_ziel) } } : null;
if (zahnrad) kopf.zahnrad = { ziel: zahnrad };
const fehler = t => [{ json: { inhalt: { seite: kopf, bloecke: [{ typ: 'hinweis', ton: 'warn', text: t }] } } }];
if (D.ok !== true) return fehler('Die Seite konnte nicht geladen werden. Bitte neu laden.');
const ZU = D.zustand || {};
const zahl = n => Number(n || 0).toLocaleString('de-DE');

// ---------- Morgen-Briefing ----------
if (seite === 'morgen-briefing') {
  const B = D.b;
  if (!B || typeof B !== 'object') return fehler('Das Morgen-Briefing ist nicht eingerichtet.');
  const an = B.an === true, kal = String(D.kalender || '') !== '';
  const ueberblick = { kennzahlen: [
    { label: 'Uhrzeit', wert: an ? String(B.uhrzeit || '–') : 'aus', neben: an ? 'täglich' : 'ausgeschaltet', ton: an ? '' : 'warn' },
    { label: 'Heute', wert: B.laeuft ? 'unterwegs' : B.heute ? 'geschickt' : 'offen', neben: B.heute ? 'im Chat' : '' },
    { label: 'Kalender', wert: kal ? 'verbunden' : 'fehlt', neben: kal ? 'Termine im Briefing' : 'ohne Termine', ton: kal ? '' : 'warn' }],
    karten: [
      { titel: 'Offen', leer: 'Nichts offen.', eintraege: [].concat(
        !an ? [{ marke: { text: 'aus', ton: 'warn' }, text: 'Das Morgen-Briefing ist für dich ausgeschaltet.', ziel: zahnrad || undefined, ziel_text: zahnrad ? 'Einstellungen' : undefined }] : [],
        !kal ? [{ marke: { text: 'fehlt', ton: 'grau' }, text: 'Kein Kalender hinterlegt.', ziel: { seite: 'einstellungen', parameter: { bereich: 'kalender' } }, ziel_text: 'Einstellungen' }] : [])
        .map(e => { if (!e.ziel) { delete e.ziel; delete e.ziel_text; } return e; }) },
      { titel: 'Meldungen', leer: 'Keine Meldungen.', eintraege: B.laeuft ? [{ marke: { text: 'läuft', ton: 'info' }, text: 'Dein Briefing ist unterwegs in den Chat.' }]
        : B.heute ? [{ marke: { text: 'heute', ton: 'ok' }, text: 'Das Briefing für heute ist geschickt.' }] : [] }] };
  if (an && !B.laeuft) kopf.hauptaktion = { text: 'Jetzt schicken', aktion: 'start', werte: { was: 'briefing' }, frage: 'Briefing jetzt schicken? Das geplante Briefing kommt trotzdem zur eingestellten Uhrzeit.' };
  // BA10: letzte Briefings (Text im Seitenfenster)
  const MB = D.mb && D.mb.ok === true && Array.isArray(D.mb.liste) ? D.mb.liste.filter(x => x && /^[0-9]{1,12}$/.test(String(x.id))) : [];
  const erW = String(($('Parameter').first().json || {}).er || '');
  const hierB = extra => ({ seite: 'morgen-briefing', parameter: Object.assign({}, extra || {}), anker: 'a-ergebnisse' });
  const abschnitte = [{ id: 'ergebnisse', titel: 'Letzte Briefings', zahl: zahl(MB.length), offen_standard: MB.length > 0,
    info: 'Deine letzten fünf Morgen-Briefings zum Nachlesen. Ältere stehen unter Benachrichtigungen › Ergebnisse.',
    inhalt: [{ typ: 'liste', leer: 'Noch kein Briefing gespeichert. Es erscheint hier nach dem nächsten Versand.',
      eintraege: MB.map(x => ({ text: String(x.titel || 'Morgen-Briefing'), neben: String(x.zeit || ''), ziel: hierB({ er: String(x.id) }), ziel_text: 'Lesen' })) }] }];
  const bausteine = t => { const aus = [];
    for (const abs of String(t || '').split(/\n{2,}/)) { const z = abs.split('\n').map(x => x.trim()).filter(Boolean); if (!z.length) continue;
      if (z.length === 1) { aus.push({ typ: 'text', text: z[0] }); continue; } let st = 0;
      if (/:$/.test(z[0]) || (z[0].length <= 60 && !/^[-•]/.test(z[0]))) { aus.push({ typ: 'unterueberschrift', text: z[0].replace(/:$/, '') }); st = 1; }
      aus.push({ typ: 'liste', eintraege: z.slice(st).map(x => ({ text: x.replace(/^[-•]\s*/, '') })) }); }
    return aus.length ? aus : [{ typ: 'text', ton: 'grau', text: 'Kein Text gespeichert.' }]; };
  const selB = erW ? MB.find(x => String(x.id) === erW) : null;
  const fenster = selB ? [{ id: 'ergebnis', art: 'seitenfenster', offen: true, titel: String(selB.titel || 'Morgen-Briefing'), untertitel: String(selB.zeit || ''),
    schliessen_ziel: hierB({}), inhalt: bausteine(selB.text) }] : [];
  return [{ json: { inhalt: { seite: kopf, ueberblick: knapp(ueberblick), abschnitte, fenster } } }];
}

// ---------- System-Mails ----------
const M = D.m;
if (!M || typeof M !== 'object') return fehler('Die System-Mails konnten nicht geladen werden. Bitte neu laden.');
const liste = Array.isArray(M.liste) ? M.liste : [];
const tage = String(M.tage || '14');
const zeit = s => { const m = /^(\d{2})\.(\d{2})\.(\d{4})\s+(\d{2}):(\d{2})/.exec(String(s || '')); return m ? m[3] + m[2] + m[1] + m[4] + m[5] : ''; };
const jetzt = new Date(), vor24 = new Date(jetzt.getTime() - 864e5);
const stempel = d => { const t = new Intl.DateTimeFormat('de-DE', { timeZone: 'Europe/Berlin', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false }).formatToParts(d);
  const g = k => (t.find(x => x.type === k) || {}).value || ''; return g('year') + g('month') + g('day') + g('hour') + g('minute'); };
const ab24 = stempel(vor24);
const letzte24 = liste.filter(m => zeit(m.zeit) >= ab24).length;
const absender = new Set(liste.map(m => String(m.absender || '').toLowerCase()).filter(Boolean)).size;
const postfaecher = new Set(liste.map(m => String(m.postfach || '')).filter(Boolean)).size;
const ERG = D.erg && typeof D.erg === 'object' ? D.erg : null;
const ZR = { '1': 'heute und gestern', '7': '7 Tage', '14': '14 Tage', '30': '30 Tage' };
const ueberblick = { kennzahlen: [
  { label: 'System-Mails', wert: zahl(liste.length) + (liste.length >= 200 ? '+' : ''), neben: ZR[tage] || '' },
  { label: 'Letzte 24 h', wert: zahl(letzte24), neben: '' },
  { label: 'Absender', wert: zahl(absender), neben: '' },
  { label: 'Postfächer', wert: zahl(postfaecher), neben: '' }],
  karten: [
    // Layout 12 (Plan 39, Regel 13): keine Karte „Offen“ – auf dieser Seite gibt es nichts Offenes, sie war immer leer
    { titel: 'Meldungen', leer: 'Keine System-Mails.', eintraege: liste.slice(0, 5).map(m => ({ text: String(m.betreff || '(ohne Betreff)'), neben: String(m.zeit || '') })) }] };
const SP = ['zeit', 'betreff', 'absender', 'begruendung'];
const s0 = (ZU['system-mails.liste'] || {}).sortierung || {};
const so = { spalte: SP.includes(s0.spalte) ? s0.spalte : 'zeit', richtung: s0.richtung === 'auf' || s0.richtung === 'ab' ? s0.richtung : 'ab' };
const wert = (m, sp) => sp === 'zeit' ? zeit(m.zeit) : String(m[sp] || '').toLowerCase();
const sortiert = liste.map((m, i) => [m, i]).sort((a, b) => { const c = String(wert(a[0], so.spalte)).localeCompare(String(wert(b[0], so.spalte)), 'de', { numeric: true }); return (so.richtung === 'ab' ? -c : c) || a[1] - b[1]; }).map(x => x[0]);
// Layout 12 (Plan 39, Koordinator 24.10.2026, E8/E10): 10 je Seite wie die Anzeige – „Alle markieren“ zählt dann genau die sichtbare Seite
const JE = 10;
const seiten = Math.max(1, Math.ceil(sortiert.length / JE)), bl = Math.min(seiten, Math.max(1, Number((E.seiten || {}).liste) || 1));
const abschnitte = [];
if (ERG) abschnitte.push({ id: 'zusammenfassung', titel: 'Letzte Zusammenfassung', zahl: ERG.tage ? String(ERG.tage) + ' Tage' : '', offen_standard: true, inhalt: [{ typ: 'text', text: String(ERG.text || '') }] });
abschnitte.push({ id: 'liste', titel: 'System-Mails', zahl: zahl(liste.length), offen_standard: true, inhalt: [
  { typ: 'filter', id: 'liste', label: 'System-Mails filtern', felder: [{ typ: 'auswahl', name: 'tage', label: 'Zeitraum', wert: tage, optionen: Object.keys(ZR).map(k => ({ wert: k, text: ZR[k] })) }] },
  { typ: 'tabelle', id: 'liste', titel: 'System-Mails', spalten: [{ schluessel: 'zeit', titel: 'Zeit', sortierbar: true }, { schluessel: 'betreff', titel: 'Betreff', sortierbar: true },
    { schluessel: 'absender', titel: 'Absender', sortierbar: true }, { schluessel: 'begruendung', titel: 'Einordnung', sortierbar: true }],
    zeilen: sortiert.slice((bl - 1) * JE, bl * JE).map(m => ({ zellen: { zeit: String(m.zeit || ''), betreff: { text: String(m.betreff || '(ohne Betreff)'), fett: true, neben: String(m.postfach || '') },
      absender: String(m.absender || ''), begruendung: String(m.begruendung || '') } })),
    sortierung: so, seite: bl, je_seite: JE, gesamt: sortiert.length, leer: 'Keine System-Mails in diesem Zeitraum.' }] });
kopf.hauptaktion = { text: 'Zusammenfassen', aktion: 'systemmails', werte: { tage }, frage: 'Zusammenfassung der System-Mails der letzten ' + (ZR[tage] || tage + ' Tage') + ' erstellen? Das dauert etwa eine halbe Minute.' };
return [{ json: { inhalt: { seite: kopf, ueberblick: knapp(ueberblick), abschnitte } } }];

// Parameter (ALLY 33, Morgen-Briefing und System-Mails): Sitzung, Seite (nur die zwei eigenen), Zeitraum der System-Mails (1, 7, 14 oder 30 Tage).
// BA10: gewähltes Briefing (er, nur Ziffern).
const E = $input.first().json;
const P = E.parameter || {};
const seite = ['morgen-briefing', 'system-mails'].includes(String(E.seite || '')) ? String(E.seite) : 'morgen-briefing';
const tage = ['1', '7', '14', '30'].includes(String(P.tage || '')) ? String(P.tage) : '14';
return [{ json: { werte: [/^[0-9a-f]{64}$/.test(String(E.sitzung || '')) ? String(E.sitzung) : '', seite, tage], er: /^[0-9]{1,12}$/.test(String(P.er || '')) ? String(P.er) : '' } }];
